#' Compare Estimators
#'
#' 
#' @param data .
#' @param outcome .
#' @param unit .
#' @param time .
#' @param treatedUnit .
#' @param treatmentTime .
#' @param donorExclude .
#' @param cmpScm .
#' @param cmpPen .
#' @param cmpDem .
#' @param cmpAscm .
#' @param cmpEnet .
#' @param cmpBscm .
#' @param cmpIfe .
#' @param cmpMc .
#' @param cmpSdid .
#' @param inference .
#' @param lambda .
#' @param nFactors .
#' @param mcLambda .
#' @param bayesDraws .
#' @param optStarts .
#' @param seed .
#' @param showPath .
#' @param showGuide .
#' @param showHelp .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$guide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$helpText} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$notes} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$summary} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$pathTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$pathsPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$gapsPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$attPlot} \tab \tab \tab \tab \tab an image \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$summary$asDF}
#'
#' \code{as.data.frame(results$summary)}
#'
#' @export
compare <- function(
    data,
    outcome,
    unit,
    time,
    treatedUnit,
    treatmentTime = 2000,
    donorExclude = "",
    cmpScm = TRUE,
    cmpPen = FALSE,
    cmpDem = TRUE,
    cmpAscm = TRUE,
    cmpEnet = FALSE,
    cmpBscm = FALSE,
    cmpIfe = FALSE,
    cmpMc = FALSE,
    cmpSdid = TRUE,
    inference = FALSE,
    lambda = 0.01,
    nFactors = 1,
    mcLambda = 0.1,
    bayesDraws = 1000,
    optStarts = 5,
    seed = 1,
    showPath = FALSE,
    showGuide = FALSE,
    showHelp = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("compare requires jmvcore to be installed (restart may be required)")

    if ( ! missing(outcome)) outcome <- jmvcore::resolveQuo(jmvcore::enquo(outcome))
    if ( ! missing(unit)) unit <- jmvcore::resolveQuo(jmvcore::enquo(unit))
    if ( ! missing(time)) time <- jmvcore::resolveQuo(jmvcore::enquo(time))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(outcome), outcome, NULL),
            `if`( ! missing(unit), unit, NULL),
            `if`( ! missing(time), time, NULL))


    options <- compareOptions$new(
        outcome = outcome,
        unit = unit,
        time = time,
        treatedUnit = treatedUnit,
        treatmentTime = treatmentTime,
        donorExclude = donorExclude,
        cmpScm = cmpScm,
        cmpPen = cmpPen,
        cmpDem = cmpDem,
        cmpAscm = cmpAscm,
        cmpEnet = cmpEnet,
        cmpBscm = cmpBscm,
        cmpIfe = cmpIfe,
        cmpMc = cmpMc,
        cmpSdid = cmpSdid,
        inference = inference,
        lambda = lambda,
        nFactors = nFactors,
        mcLambda = mcLambda,
        bayesDraws = bayesDraws,
        optStarts = optStarts,
        seed = seed,
        showPath = showPath,
        showGuide = showGuide,
        showHelp = showHelp)

    analysis <- compareClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

